
const BM={"man":{"h":1.78,"mn":[-0.2762,0.0,-0.1581],"ex":[0.5524,1.78,0.3163],"n":6563,"p":"","c":"","b":"","nb":7863,"hd":"","nh":2025},"scifi":{"h":1.75,"mn":[-0.2953,0.0,-0.1442],"ex":[0.5906,1.75,0.2885],"n":11991,"p":"","c":"","b":"","nb":77442,"hd":"","nh":13866},"rosie":{"h":1.5,"mn":[-0.312,0.0,-0.2893],"ex":[0.624,1.5,0.5787],"n":11992,"p":"","c":"","b":"","nb":54792,"hd":"","nh":21192},"sorc":{"h":1.75,"mn":[-0.5383,0.0,-0.4725],"ex":[1.0765,1.75,0.945],"n":2942,"p":"","c":"","b":"","nb":10848,"hd":"","nh":2400},"worker":{"h":1.7,"mn":[-0.3289,0.0,-0.198],"ex":[0.6578,1.7,0.3961],"n":1917,"p":"","c":"","b":"","nb":5076,"hd":"","nh":2331}};
/* ===== PERSONAGENS 3D (GLB convertidos) — substituem os bonecos de caixas =====
   Se der qualquer erro aqui, o jogo continua com os bonecos antigos. */
(function(){
try{
if(typeof THREE==='undefined'||typeof S==='undefined'||typeof bots==='undefined'||typeof mkBot2==='undefined')return;
const old=mkBot2;
/* slot do personagem -> [modelo, tom, nome] */
const SLOT=[['man',0xffffff,'Homem'],['scifi',0xffffff,'Ciber'],['rosie',0xffffff,'Rosie'],['sorc',0xffffff,'Feiticeira'],['worker',0xffffff,'Operária'],
 ['worker',0xffd9b8,'Operária II'],['man',0xffc9a0,'Homem II'],['scifi',0xc8d8ff,'Ciber II'],['sorc',0xd8c8ff,'Feiticeira II']];
const b64=s=>{const a=atob(s),u=new Uint8Array(a.length);for(let i=0;i<a.length;i++)u[i]=a.charCodeAt(i);return u};
const GEO={};
function geoOf(k){
 if(GEO[k])return GEO[k];
 const d=BM[k],q=new Uint16Array(b64(d.p).buffer),pos=new Float32Array(d.n*3);
 for(let i=0;i<d.n;i++)for(let a=0;a<3;a++)pos[i*3+a]=d.mn[a]+q[i*3+a]/65535*d.ex[a];
 const cu=b64(d.c),col=new Float32Array(d.n*3);for(let i=0;i<col.length;i++)col[i]=cu[i]/255;
 const full=new THREE.BufferGeometry();
 full.setAttribute('position',new THREE.BufferAttribute(pos,3));
 const ib=new Uint16Array(b64(d.b).buffer),ih=new Uint16Array(b64(d.hd).buffer);
 const all=new Uint16Array(ib.length+ih.length);all.set(ib,0);all.set(ih,ib.length);
 full.setIndex(new THREE.BufferAttribute(all,1));full.computeVertexNormals();
 const nor=full.getAttribute('normal');
 const mk=ix=>{const g=new THREE.BufferGeometry();g.setAttribute('position',full.getAttribute('position'));g.setAttribute('normal',nor);
  g.setAttribute('color',new THREE.BufferAttribute(col,3));g.setIndex(new THREE.BufferAttribute(ix,1));g.computeBoundingSphere();g.computeBoundingBox();return g};
 return GEO[k]={body:mk(ib),head:mk(ih),h:d.h,pos}}
const LM={"man": "", "scifi": "", "rosie": "", "sorc": "", "worker": ""};const LP={"man": {"cut": 0.841, "knee": 0.4218, "cx": -0.0127, "band": 0.0301, "g": 1.0}, "scifi": {"cut": 0.9625, "knee": 0.4789, "cx": -0.0402, "band": 0.09, "g": 0.75}, "rosie": {"cut": 0.825, "knee": 0.4142, "cx": 0.0448, "band": 0.09, "g": 1.0}, "sorc": {"cut": 0.9325, "knee": 0.4648, "cx": -0.1793, "band": 0.09, "g": 0.6}, "worker": {"cut": 1.05, "knee": 0.52, "cx": -0.034, "band": 0.09, "g": 1.0}};

/* ===== PERNAS: balanço real (quadril/joelho/tornozelo) nos modelos de uma peça só ===== */
function legBuild(m,P,pos){
 const idx=[];for(let i=0;i<m.length;i++)if(m[i])idx.push(i);
 const N=idx.length,I=new Int32Array(idx),base=new Float32Array(N*3),w1=new Float32Array(N),w2=new Float32Array(N),w3=new Float32Array(N),xw=new Float32Array(N);
 const sm=t=>{t=t<0?0:t>1?1:t;return t*t*(3-2*t)};
 for(let n=0;n<N;n++){const i=I[n]*3,x=pos[i],y=pos[i+1];base[n*3]=x;base[n*3+1]=y;base[n*3+2]=pos[i+2];
  w1[n]=sm((P.cut-y)/Math.max(.01,(P.cut-P.knee)*.9));w2[n]=sm((P.knee-y)/(P.knee*.35));w3[n]=sm((.11-y)/.05);
  const q=(x-P.cx)/P.band;xw[n]=(q<-1?-1:q>1?1:q)*.5+.5}
 return{I,N,base,w1,w2,w3,xw,P}}
function legApply(L,arr,aL,aR,kL,kR){
 const P=L.P,g=P.g,cut=P.cut,kn=P.knee;aL*=g;aR*=g;kL*=g;kR*=g;
 const tL=-(aL+kL)*.75,tR=-(aR+kR)*.75;let ry=0,rz=0;
 const fk=(y0,z0,A,K,T,a1,a2,a3)=>{let th=T*a3,c=Math.cos(th),s=Math.sin(th),y=y0-.06,z=z0,ny=y*c-z*s,nz=y*s+z*c;y=ny+.06;z=nz;
  th=K*a2;c=Math.cos(th);s=Math.sin(th);y-=kn;ny=y*c-z*s;nz=y*s+z*c;y=ny+kn;z=nz;
  th=A*a1;c=Math.cos(th);s=Math.sin(th);y-=cut;ny=y*c-z*s;nz=y*s+z*c;y=ny+cut;z=nz;ry=y;rz=z};
 const{I,N,base,w1,w2,w3,xw}=L;
 for(let n=0;n<N;n++){const o=n*3,by=base[o+1],bz=base[o+2],x=xw[n];let Y=0,Z=0;
  if(x<1){fk(by,bz,aL,kL,tL,w1[n],w2[n],w3[n]);Y=ry*(1-x);Z=rz*(1-x)}
  if(x>0){fk(by,bz,aR,kR,tR,w1[n],w2[n],w3[n]);Y+=ry*x;Z+=rz*x}
  const d=I[n]*3;arr[d+1]=Y;arr[d+2]=Z}}
const dark=new THREE.MeshStandardMaterial({color:0x151515,roughness:.5,metalness:.4});
window.mkBot2=function(team,ci){
 try{
  const sl=SLOT[ci%SLOT.length],G=geoOf(sl[0]),h=G.h;
  const b={team,hp:0,p:new V(),yaw:0,lt:0,cd:1,rs:rnd()*1.5,tg:null,td:0,gt:0,sd:1,n:sl[2]};
  const g=new THREE.Group(),up=new THREE.Group();up.position.set(0,.9,0);g.add(up);
  const mat=new THREE.MeshLambertMaterial({vertexColors:true,side:THREE.DoubleSide,color:sl[1]});
  let bgeo=G.body,legUpd=null;
  try{if(G.leg===undefined)G.leg=legBuild(b64(LM[sl[0]]),LP[sl[0]],G.pos);const LD=G.leg;
   if(LD&&LD.N>20){bgeo=new THREE.BufferGeometry();const pa=new THREE.BufferAttribute(G.pos.slice(),3);bgeo.setAttribute('position',pa);
    bgeo.setAttribute('normal',G.body.getAttribute('normal'));bgeo.setAttribute('color',G.body.getAttribute('color'));bgeo.setIndex(G.body.getIndex());
    bgeo.computeBoundingSphere();bgeo.boundingSphere.radius+=.3;bgeo.computeBoundingBox();bgeo.boundingBox.expandByScalar(.3);
    let fc=(Math.random()*2)|0,ls='';
    legUpd=(aL,aR,kL,kR)=>{if((fc=(fc+1)|0)&1)return;const sg=((aL*300)|0)+','+((aR*300)|0)+','+((kL*300)|0)+','+((kR*300)|0);if(sg===ls)return;ls=sg;legApply(LD,pa.array,aL,aR,kL,kR);pa.needsUpdate=true}}
  }catch(e){bgeo=G.body;legUpd=null;try{console.error('[pernas]',e)}catch(_){}}
  const body=new THREE.Mesh(bgeo,mat),head=new THREE.Mesh(G.head,mat);
  for(const m of[body,head]){m.position.y=-.9;m.userData.bot=b;m.castShadow=true;up.add(m)}
  head.userData.head=1;
  /* arma em posição TÁTICA (low ready): coronha no ombro, cano levemente pra baixo, 2 mãos */
  const MK=sl[0],SHY=({man:1.38,scifi:1.4,rosie:1.0,sorc:1.4,worker:1.28})[MK]||.78*h,GCX=({man:0,scifi:0,rosie:.03,sorc:-.18,worker:0})[MK]||0,GBZ=({man:0,scifi:0,rosie:.1,sorc:.1,worker:0})[MK]||0;
  const PIT=.22,sc=h/1.78;
  const gun=new THREE.Group();gun.position.set(GCX+.12,SHY-.07-.9,GBZ);gun.rotation.x=PIT;gun.scale.setScalar(.9);
  const gb=(w,hh,d,x,y,z,rx)=>{const m=new THREE.Mesh(new THREE.BoxGeometry(w,hh,d),dark);m.position.set(x,y,z);if(rx)m.rotation.x=rx;m.userData.bot=b;m.castShadow=true;gun.add(m)};
  gb(.045,.1,.22,0,-.015,.11);      /* coronha */
  gb(.06,.085,.34,0,0,.39);         /* corpo */
  gb(.055,.07,.28,0,-.005,.7);      /* guarda-mão */
  gb(.02,.02,.26,0,.005,.96);       /* cano */
  gb(.032,.032,.05,0,.005,1.1);     /* quebra-chamas */
  gb(.04,.16,.07,0,-.12,.45,-.22);  /* carregador */
  gb(.04,.1,.05,0,-.09,.3,.3);      /* empunhadura */
  gb(.022,.035,.12,0,.06,.45);      /* mira traseira */
  gb(.012,.045,.012,0,.05,.85);     /* massa de mira */
  up.add(gun);gun.updateMatrix();
  /* braços novos: mão de tiro na empunhadura, mão de apoio no guarda-mão */
  const gp=(x,y,z)=>new V(x,y,z).applyMatrix4(gun.matrix);
  const HR=gp(0,-.1,.3),HL=gp(0,-.05,.6);
  const AC=({man:[0x2f4059,0xe0a080],scifi:[0xe3b595,0xe3b595],rosie:[0xdcd2d2,0xf0cdb8],sorc:[0x3a2c2c,0xd0a890],worker:[0xb87a58,0xb87a58]})[MK]||[0x555555,0xd9a77a];
  const tint=new THREE.Color(sl[1]);
  const amat=c=>new THREE.MeshLambertMaterial({color:new THREE.Color(c).multiply(tint)});
  const mS=amat(AC[0]),mH=amat(AC[1]);
  const seg=(a,c,r1,r2,m)=>{const d=c.clone().sub(a),mm=new THREE.Mesh(new THREE.CylinderGeometry(r2,r1,d.length(),8),m);mm.quaternion.setFromUnitVectors(new V(0,1,0),d.clone().normalize());mm.position.copy(a.clone().add(c).multiplyScalar(.5));mm.userData.bot=b;mm.castShadow=true;up.add(mm)};
  const ball=(p,r,m)=>{const mm=new THREE.Mesh(new THREE.SphereGeometry(r,8,6),m);mm.position.copy(p);mm.userData.bot=b;mm.castShadow=true;up.add(mm)};
  const arm=(sx,H)=>{const S=new V(GCX+sx,SHY-.04-.9,0),E=S.clone().add(H).multiplyScalar(.5);E.x+=sx>0?.07:-.07;E.y-=.1*sc+.05;E.z-=.02;seg(S,E,.062*sc,.05*sc,mS);seg(E,H,.05*sc,.04*sc,mH);ball(E,.056*sc,mS);ball(H,.048*sc,mH)};
  arm(.2,HR);arm(-.2,HL);
  b.gun=gun;b.hm=HR.clone().add(HL).multiplyScalar(.5).add(new V(0,.9,0));b.shy=SHY;
  /* marca do time: anel no chão + bolinha sobre a cabeça */
  const tc=team?0xe03a3a:0x2e8bff;
  const ring=new THREE.Mesh(new THREE.RingGeometry(.38,.5,24),new THREE.MeshBasicMaterial({color:tc,side:THREE.DoubleSide,transparent:true,opacity:.85}));
  ring.rotation.x=-Math.PI/2;ring.position.y=.03;ring.raycast=()=>{};g.add(ring);
  const dot=new THREE.Mesh(new THREE.SphereGeometry(.07,8,6),new THREE.MeshBasicMaterial({color:tc}));
  dot.position.y=h+.3;dot.raycast=()=>{};g.add(dot);
  /* rig "falso" compatível com a animação existente (inclinação, balanço, queda) */
  const o3=()=>new THREE.Object3D();
  b.rig={hip:[o3(),o3()],kp:[o3(),o3()],ft:[o3(),o3()],up,lx:0,lz:0,sp:0,fs:0,ss:0,ph:Math.random()*6,si:0,fl:0,legUpd};
  g.visible=false;S.add(g);b.mesh=g;return b
 }catch(e){try{console.error('[personagens3d]',e)}catch(_){}return old(team,ci)}};
/* nomes no lobby */
try{SLOT.forEach((s,i)=>{if(CH[i])CH[i][0]=s[2];if(typeof CN!=='undefined')CN[i]=s[2]})}catch(e){}
/* refaz os bots que já existiam */
const bl=[0,1,5,6],rd=[2,3,4,7,8];
bots.forEach(b=>S.remove(b.mesh));bots.length=0;
bl.forEach(i=>bots.push(mkBot2(0,i)));rd.forEach(i=>bots.push(mkBot2(1,i)));
if(typeof ents!=='undefined'){ents.length=0;ents.push(P,...bots)}
if(typeof showCh==='function'&&typeof pg!=='undefined'&&typeof PS!=='undefined'){try{showCh()}catch(e){}}
console.log('[personagens3d] ok');
}catch(e){try{console.error('[personagens3d]',e)}catch(_){}}
})();

